// ─── Configuration de la veille ────────────────────────────────────────────
// Seul endroit à modifier pour régler la veille au quotidien.

// ─── Reprise de l'état précédent ───────────────────────────────────────────
// Le rapport précédent a laissé sa date et la liste des liens déjà envoyés
// dans /data/rapports/.etat.json. On repart de là plutôt que d'une fenêtre
// fixe : sinon une exécution retardée (Mac éteint) laisse un trou, et une
// exécution manuelle le même jour produit des doublons.
let dernierRun = null;
let dejaEnvoyes = [];
// En mode de stockage « filesystem », la propriété data est VIDE et le contenu
// vit sur disque : il faut passer par le helper, sinon l'état n'est jamais relu
// et le rapport repart chaque fois d'une fenêtre fixe.
try {
  const b = $input.first()?.binary?.data;
  if (b) {
    let brut = '';
    try {
      const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
      if (buf?.length) brut = buf.toString('utf8');
    } catch (e) { /* helper indisponible */ }
    if (!brut && b.data) brut = Buffer.from(b.data, 'base64').toString('utf8');
    if (brut) {
      const etat = JSON.parse(brut);
      if (etat.dernierRun) dernierRun = etat.dernierRun;
      if (Array.isArray(etat.liens)) dejaEnvoyes = etat.liens;
    }
  }
} catch (e) { /* premier lancement, ou état illisible : fenêtre par défaut */ }

const config = {
  // Destinataire du rapport PDF
  destinataire: 'leogaallus@gmail.com, olivia.gallus@gmail.com, g.gallus@hotmail.com',
  expediteur: 'leogaallus@gmail.com',

  // Fenêtre de collecte : on garde les articles des N derniers jours
  fenetreJours: 3,          // fenêtre par défaut, au tout premier lancement
  fenetreMaxJours: 8,       // plafond après une longue absence

  // Garde-fous de volume
  maxArticlesParSource: 45,   // après filtrage par date
  maxUneParSource: 8,        // articles affichés en carte dans la section du journal
  // Vivier de l'appariement : indépendant du nombre de cartes. Un article
  // développé remonte dans « L'essentiel » même s'il n'est pas en carte, donc
  // restreindre ce vivier appauvrit directement le rapport.
  maxCandidatsParSource: 18,
  maxEnrichissements: 90,     // pages visitées au maximum (résumé ou image manquants)
  maxArticlesLibres: 90,     // plafond par source libre (France Info, France 24, RFI, Euronews)

  // Blocs « Développement » : texte tiré des sources libres, rattaché aux unes
  developpements: {
    actif: true,
    modeleEmbedding: 'bge-m3',
    ollama: 'http://host.docker.internal:11434',  // Ollama tourne sur le Mac, pas dans Docker
    seuil: 0.65,              // mesuré : au-dessus de 0,65, aucun rapprochement erroné
    poidsSemantique: 0.65,    // le reste (0,35) vient du recouvrement des noms propres
    maxBlocs: 60,             // nb max de blocs « Développement » par rapport
    paragraphes: 3,           // paragraphes repris par bloc
    maxCaracteres: 1200,
  },

  // Détection des sujets couverts par plusieurs journaux (indice de Jaccard sur les titres)
  seuilSujetCommun: 0.40,

  // Contrôle qualité final. Deux passes : une déterministe (coupures, doublons,
  // longueurs) et une sémantique confiée à un modèle local, qui juge ce qu'une
  // expression régulière ne sait pas voir — parasite, incohérence, hors-sujet.
  controleQualite: {
    actif: true,
    // Deux modèles, chacun sur ce qu'il fait le mieux — mesuré, pas supposé.
    // gemma2 juge le mieux (5/6) mais rédige mal : il produisait
    // « BUDGET TRANSMISSIONS » là où llama3.1 donne « BUDGET 2027 ».
    modele: 'gemma2:9b',            // jugement qualité : 5/6 en 7,8 s
    modeleEtiquettes: 'llama3.1:8b', // rédaction des thèmes : nettement plus juste
    ollama: 'http://host.docker.internal:11434',
    tailleLot: 10,            // paragraphes jugés par appel
    maxLots: 8,
  },

  // Taille maximale du PDF joint. Au-delà, le rapport est régénéré sans images
  // (Gmail refuse au-delà de 25 Mo ; on garde de la marge pour l'encodage MIME).
  maxPdfMo: 20,

  // Nombre de chiffres marquants en page de garde
  maxImages: 80,             // images rapatriées et intégrées en base64
  maxBrevesParSource: 16,    // brèves affichées par journal (le reste est écarté)

  maxTempsForts: 5,          // sujets majeurs, en grand format
  maxEssentiel: 22,          // total des sujets mis en tête (temps forts inclus)
  maxEssentielSansDev: 7,    // parmi eux, combien au maximum sans développement
  maxChiffresMarquants: 6,     // 2 rangées pleines de la grille à 3 colonnes
};

// Fenêtre réelle : depuis le dernier rapport, bornée pour éviter un pavé
// après une longue absence.
let fenetre = config.fenetreJours;
if (dernierRun) {
  const ecoule = (Date.now() - new Date(dernierRun).getTime()) / 86400000;
  if (ecoule > 0.2) fenetre = Math.min(Math.max(ecoule, 0.5), config.fenetreMaxJours);
}

return [{ json: { ...config, fenetreJours: Math.round(fenetre * 100) / 100, dernierRun, dejaEnvoyes } }];

// ─── Liste des flux RSS à interroger ───────────────────────────────────────
// Un item de sortie = un flux. Le nœud HTTP suivant s'exécute une fois par item.
// Flux vérifiés le 07/09/2026 (tous en HTTP 200).

// dejaEnvoyes reste dans le nœud Configuration : recopié sur chaque article,
// il alourdirait inutilement toute la chaîne.
const { dejaEnvoyes, ...cfg } = $input.first().json;

const flux = [
  // ─── AGENDA : les 5 quotidiens. Ils définissent ce que la presse traite. ───
  // Le Monde
  { source: 'Le Monde',   domaine: 'lemonde.fr',    couleur: '#1a1a1a', rubrique: 'une', libelle: 'À la une',
    url: 'https://www.lemonde.fr/rss/une.xml' },
  { source: 'Le Monde',   domaine: 'lemonde.fr',    couleur: '#1a1a1a', rubrique: 'fil', libelle: 'En continu',
    url: 'https://www.lemonde.fr/rss/en_continu.xml' },

  // Le Figaro
  { source: 'Le Figaro',  domaine: 'lefigaro.fr',   couleur: '#00539f', rubrique: 'une', libelle: 'Actualités',
    url: 'https://www.lefigaro.fr/rss/figaro_actualites.xml' },
  { source: 'Le Figaro',  domaine: 'lefigaro.fr',   couleur: '#00539f', rubrique: 'fil', libelle: 'Flash actu',
    url: 'https://www.lefigaro.fr/rss/figaro_flash-actu.xml' },

  // Le Parisien  (flux sans date ni résumé : complétés par l'étape d'enrichissement)
  { source: 'Le Parisien', domaine: 'leparisien.fr', couleur: '#e2001a', rubrique: 'une', libelle: 'À la une',
    url: 'https://feeds.leparisien.fr/leparisien/rss/une' },
  { source: 'Le Parisien', domaine: 'leparisien.fr', couleur: '#e2001a', rubrique: 'fil', libelle: 'Fil général',
    url: 'https://feeds.leparisien.fr/leparisien/rss' },

  // Libération
  { source: 'Libération', domaine: 'liberation.fr', couleur: '#e10600', rubrique: 'une', libelle: 'Toutes les infos',
    url: 'https://www.liberation.fr/arc/outboundfeeds/rss-all/?outputType=xml' },

  // La Croix
  { source: 'La Croix',   domaine: 'la-croix.com',  couleur: '#0069b4', rubrique: 'une', libelle: 'Tous univers',
    url: 'https://www.la-croix.com/RSS/UNIVERS' },
  { source: 'La Croix',   domaine: 'la-croix.com',  couleur: '#0069b4', rubrique: 'fil', libelle: 'France',
    url: 'https://www.la-croix.com/RSS/UNIVERS_WFRA' },

  // ─── PROFONDEUR : sources libres, texte intégral accessible. ──────────────
  // Elles n'ont pas de section dans le rapport : elles alimentent les blocs
  // « Développement » rattachés aux articles à la une des quotidiens.
  { source: 'France Info', domaine: 'franceinfo.fr',  couleur: '#0a3d62', role: 'libre',
    url: 'https://www.franceinfo.fr/titres.rss' },
  { source: 'France 24',   domaine: 'france24.com',   couleur: '#0a3d62', role: 'libre',
    url: 'https://www.france24.com/fr/rss' },
  { source: 'France 24',   domaine: 'france24.com',   couleur: '#0a3d62', role: 'libre',
    url: 'https://www.france24.com/fr/france/rss' },
  { source: 'RFI',         domaine: 'rfi.fr',         couleur: '#0a3d62', role: 'libre',
    url: 'https://www.rfi.fr/fr/france/rss' },
  { source: 'RFI',         domaine: 'rfi.fr',         couleur: '#0a3d62', role: 'libre',
    url: 'https://www.rfi.fr/fr/monde/rss' },
  { source: 'Euronews',    domaine: 'euronews.com',   couleur: '#0a3d62', role: 'libre',
    url: 'https://fr.euronews.com/rss?level=theme&name=news' },
  // Rubriques supplémentaires : plus le vivier est large, plus d'articles des
  // quotidiens trouvent leur équivalent développé.
  { source: 'France Info', domaine: 'franceinfo.fr',  couleur: '#0a3d62', role: 'libre',
    url: 'https://www.franceinfo.fr/politique.rss' },
  { source: 'France Info', domaine: 'franceinfo.fr',  couleur: '#0a3d62', role: 'libre',
    url: 'https://www.franceinfo.fr/monde.rss' },
  { source: 'France Info', domaine: 'franceinfo.fr',  couleur: '#0a3d62', role: 'libre',
    url: 'https://www.franceinfo.fr/economie.rss' },
  { source: 'France Info', domaine: 'franceinfo.fr',  couleur: '#0a3d62', role: 'libre',
    url: 'https://www.franceinfo.fr/societe.rss' },
  { source: 'France 24',   domaine: 'france24.com',   couleur: '#0a3d62', role: 'libre',
    url: 'https://www.france24.com/fr/europe/rss' },
  { source: 'RFI',         domaine: 'rfi.fr',         couleur: '#0a3d62', role: 'libre',
    url: 'https://www.rfi.fr/fr/economie/rss' },
];

return flux.map((f) => ({ json: { role: 'agenda', rubrique: 'fil', libelle: '', ...f, cfg } }));

// ─── Normalisation des flux RSS ────────────────────────────────────────────
// Entrée  : sortie du nœud XML (une entrée par flux)
// Sortie  : un item par article, schéma unifié, dédoublonné et filtré par date.

const fluxItems = $('Liste des flux').all();
const cfg = fluxItems[0].json.cfg;

// ── Utilitaires de lecture XML (xml2js : explicitArray=false, attrkey='$') ──
const asArray = (v) => (v == null ? [] : Array.isArray(v) ? v : [v]);
const txt = (v) => {
  if (v == null) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'number') return String(v);
  if (typeof v === 'object') return txt(v._ ?? v['#text'] ?? '');
  return '';
};
// Les attributs XML se retrouvent soit sous « $ » (attrkey par défaut), soit
// fusionnés dans l'objet parent selon la configuration du nœud XML. On accepte
// les deux formes : sans cela, les images de media:content sont perdues.
const attr = (v, name) => {
  if (!v || typeof v !== 'object') return '';
  if (v.$ && v.$[name] != null) return v.$[name];
  if (v[name] != null && typeof v[name] !== 'object') return v[name];
  if (v['@' + name] != null) return v['@' + name];
  if (v.$$ && v.$$[name] != null) return v.$$[name];
  return '';
};

// Retire les balises HTML éventuellement présentes dans les descriptions
const deTag = (s) =>
  String(s)
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, '’')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();

// ── Identification du journal par le domaine du lien (robuste aux décalages) ─
const JOURNAUX = [
  { test: /(^|\.)lemonde\.fr/i,    source: 'Le Monde',    couleur: '#1a1a1a' },
  { test: /(^|\.)lefigaro\.fr/i,   source: 'Le Figaro',   couleur: '#00539f' },
  { test: /(^|\.)leparisien\.fr/i, source: 'Le Parisien', couleur: '#e2001a' },
  { test: /(^|\.)liberation\.fr/i, source: 'Libération',  couleur: '#e10600' },
  { test: /(^|\.)la-croix\.com/i,  source: 'La Croix',    couleur: '#0069b4' },
  // sources libres (profondeur) — pas de section propre dans le rapport
  { test: /(^|\.)(?:france)?tvinfo\.fr|(^|\.)franceinfo\.fr/i, source: 'France Info', couleur: '#0a3d62', role: 'libre' },
  { test: /(^|\.)france24\.com/i,  source: 'France 24',   couleur: '#0a3d62', role: 'libre' },
  { test: /(^|\.)rfi\.fr/i,        source: 'RFI',         couleur: '#0a3d62', role: 'libre' },
  { test: /(^|\.)euronews\.com/i,  source: 'Euronews',    couleur: '#0a3d62', role: 'libre' },
];
const identifier = (lien) => {
  let host = '';
  try { host = new URL(lien).hostname; } catch (e) { host = String(lien); }
  return JOURNAUX.find((j) => j.test.test(host)) || null;
};

// ── Datation ───────────────────────────────────────────────────────────────
// 1) <pubDate> / <dc:date>  2) date contenue dans l'URL (Le Parisien n'en a pas d'autre)
const dateDepuisUrl = (lien) => {
  const u = String(lien);
  let m = u.match(/[-/](\d{2})-(\d{2})-(20\d{2})[-/.]/);          // -07-09-2026-  (Le Parisien)
  if (m) return new Date(`${m[3]}-${m[2]}-${m[1]}T09:00:00+02:00`);
  m = u.match(/[-/_](20\d{2})(\d{2})(\d{2})(?:[-_/.]|$)/);        // -20260907     (Figaro, Libé, La Croix)
  if (m) return new Date(`${m[1]}-${m[2]}-${m[3]}T09:00:00+02:00`);
  m = u.match(/\/(20\d{2})\/(\d{2})\/(\d{2})\//);                 // /2026/09/07/  (Le Monde)
  if (m) return new Date(`${m[1]}-${m[2]}-${m[3]}T09:00:00+02:00`);
  return null;
};
const lireDate = (it, lien) => {
  for (const cle of ['pubDate', 'dc:date', 'date', 'published', 'updated']) {
    const brut = txt(it[cle]);
    if (brut) {
      const d = new Date(brut.trim());
      if (!isNaN(d)) return { date: d, source: 'flux' };
    }
  }
  const d = dateDepuisUrl(lien);
  return d && !isNaN(d) ? { date: d, source: 'url' } : { date: null, source: 'aucune' };
};

// ── Image de l'article ─────────────────────────────────────────────────────
const urlDe = (v) => {
  if (!v) return '';
  if (typeof v === 'string') return /^https?:/i.test(v) ? v : '';
  return attr(v, 'url');
};
const lireImage = (it) => {
  for (const cle of ['media:content', 'media:thumbnail', 'image', 'enclosure']) {
    for (const v of asArray(it[cle])) {
      if (cle === 'enclosure') {
        const type = attr(v, 'type');
        if (type && !/^image\//i.test(type)) continue;
      }
      const u = urlDe(v);
      if (u) return u;
    }
  }
  // Dernier recours : une image citée dans le contenu enrichi du flux
  const html = txt(it['content:encoded']) || txt(it.description);
  const m = String(html).match(/<img[^>]+src=["']([^"']+)["']/i);
  return m ? m[1] : '';
};

// ── Parcours des flux ──────────────────────────────────────────────────────
const maintenant = new Date();
const limite = new Date(maintenant.getTime() - cfg.fenetreJours * 86400000);
const parUrl = new Map();
const diag = [];
// Articles déjà partis dans un rapport précédent : on ne les reprend pas.
const dejaVus = new Set($('Configuration').first().json.dejaEnvoyes || []);

$input.all().forEach((entree, i) => {
  const meta = fluxItems[Math.min(i, fluxItems.length - 1)].json;
  const doc = entree.json;
  const canal = doc?.rss?.channel ?? doc?.channel ?? doc?.feed ?? null;
  const bruts = asArray(canal?.item ?? canal?.entry ?? []);

  if (!canal || bruts.length === 0) {
    diag.push({ flux: meta.url, source: meta.source, articles: 0, erreur: doc?.error ? String(doc.error).slice(0, 200) : 'flux vide ou illisible' });
    return;
  }

  let retenus = 0;
  for (const it of bruts) {
    const lien = (txt(it.link) || txt(it.guid) || attr(asArray(it.link)[0], 'href')).trim();
    if (!lien || !/^https?:/i.test(lien)) continue;

    const journal = identifier(lien) || { source: meta.source, couleur: meta.couleur };
    const titre = deTag(txt(it.title));
    if (!titre) continue;

    const { date, source: origineDate } = lireDate(it, lien);
    // Sans date exploitable on ne peut pas garantir la fraîcheur : on écarte.
    if (!date) continue;
    if (date < limite || date > new Date(maintenant.getTime() + 86400000)) continue;

    const cle = lien.split('?')[0].replace(/\/$/, '');
    if (dejaVus.has(cle)) continue;
    const existant = parUrl.get(cle);
    const article = {
      titre,
      lien,
      resume: deTag(txt(it.description) || txt(it['content:encoded']) || txt(it.summary)),
      date: date.toISOString(),
      dateOrigine: origineDate,
      source: journal.source,
      couleur: journal.couleur,
      role: journal.role || meta.role || 'agenda',
      rubrique: (journal.role || meta.role) === 'libre' ? 'libre' : meta.rubrique,
      fluxLibelle: meta.libelle,
      categorie: deTag(asArray(it.category).map(txt).filter(Boolean).join(' · ')),
      auteur: deTag(txt(it['dc:creator'])),
      image: lireImage(it),
    };

    // Un article vu dans « une » et dans « fil » reste en « une »
    if (existant) {
      if (existant.rubrique === 'fil' && article.rubrique === 'une') parUrl.set(cle, { ...existant, rubrique: 'une', fluxLibelle: article.fluxLibelle });
      if (!existant.resume && article.resume) parUrl.get(cle).resume = article.resume;
      if (!existant.image && article.image) parUrl.get(cle).image = article.image;
      continue;
    }
    parUrl.set(cle, article);
    retenus++;
  }
  diag.push({ flux: meta.url, source: meta.source, rubrique: meta.rubrique, recus: bruts.length, retenus });
});

// ── Plafond par journal, les plus récents d'abord ──────────────────────────
const tous = [...parUrl.values()].sort((a, b) => new Date(b.date) - new Date(a.date));
const compte = {};
const retenus = [];
for (const a of tous) {
  compte[a.source] = (compte[a.source] || 0) + 1;
  const plafond = a.role === 'libre' ? cfg.maxArticlesLibres : cfg.maxArticlesParSource;
  if (compte[a.source] <= plafond) retenus.push(a);
}

if (retenus.filter((a) => a.role !== 'libre').length === 0) {
  throw new Error('Aucun article collecté sur la fenêtre demandée. Diagnostic : ' + JSON.stringify(diag));
}

return retenus.map((a, idx) => ({
  json: {
    ...a,
    id: idx,
    // On visite aussi la page d'un article SANS IMAGE, et plus seulement sans
    // résumé : un article du Figaro ou de La Croix absent du flux en images
    // n'était jamais visité, alors que sa page porte une balise og:image.
    // Inutile en revanche d'insister sur Le Monde (HTTP 402) et Libération
    // (HTTP 403), qui refusent l'accès automatisé.
    besoinEnrichissement: a.role !== 'libre'
      && !/lemonde\.fr|liberation\.fr/.test(a.lien)
      && (!a.resume || a.resume.length < 40 || !a.image),
    cfg,
    diag: idx === 0 ? diag : undefined,
  },
}));

// ─── Sélection des articles à compléter ────────────────────────────────────
// Certains flux (Le Parisien) ne renvoient que titre + lien.
// On prépare ici la liste des pages à consulter pour récupérer les balises <meta>.
// Aucune page n'est téléchargée si tous les flux sont déjà complets : on émet
// alors un item sentinelle pour que la branche reste active dans n8n.

const articles = $input.all().map((i) => i.json);
const cfg = articles[0].cfg;

const aCompleter = articles
  .filter((a) => a.besoinEnrichissement)
  .slice(0, cfg.maxEnrichissements);

if (aCompleter.length === 0) {
  return [{ json: { lien: articles[0].lien, sentinelle: true } }];
}

return aCompleter.map((a) => ({ json: { lien: a.lien, sentinelle: false } }));

// ─── Fusion des métadonnées récupérées sur les pages ───────────────────────
// Entrée : HTML brut des pages (aligné sur « Préparer enrichissement »).
// On extrait og:description / article:published_time / og:image, puis on
// refusionne avec la liste complète d'articles issue de la normalisation.

const articles = $('Normaliser les articles').all().map((i) => ({ ...i.json }));
const cibles = $('Préparer enrichissement').all().map((i) => i.json);
const pages = $input.all();
const cfg = articles[0].cfg;

// Le Parisien tronque og:description et twitter:description à 144 caractères
// (« …sur Aryna Sabalenk ») mais publie le texte entier dans description.
// Prendre la première balise trouvée revenait donc à choisir la version
// amputée : on retient désormais la meilleure, pas la première.
const meilleureDescription = (html, cles) => {
  const candidats = [];
  for (const cle of cles) {
    const v = meta(html, [cle]);
    if (v) candidats.push(v);
  }
  if (!candidats.length) return '';
  const complet = (t) => /[.!?…»"']\s*$/.test(String(t).trim());
  const entiers = candidats.filter(complet);
  const pool = entiers.length ? entiers : candidats;
  return pool.reduce((a, b) => (b.length > a.length ? b : a));
};

const meta = (html, cles) => {
  for (const cle of cles) {
    const re = new RegExp(
      '<meta[^>]*(?:property|name)\\s*=\\s*["\']' + cle + '["\'][^>]*>',
      'i'
    );
    const balise = html.match(re);
    if (!balise) continue;
    const val = balise[0].match(/content\s*=\s*["']([^"']*)["']/i);
    if (val && val[1].trim()) return val[1].trim();
  }
  return '';
};
const decode = (s) =>
  String(s)
    .replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#0?39;|&apos;/gi, '’')
    .replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&nbsp;/gi, ' ')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n))
    .replace(/\s+/g, ' ').trim();

// Les URL de redimensionnement du Parisien sont signées : impossible d'y changer
// la taille après coup. On cherche donc dans la page la plus petite variante déjà
// signée pour la même image (≥ 600 px), sans quoi le PDF gonfle de plusieurs Mo
// par article. La carte ne fait que 42 mm, soit ~500 px à l'impression.
const imageLegere = (html, defaut) => {
  if (!defaut || !/leparisien\.fr\/resizer/.test(defaut)) return defaut;
  const fichier = defaut.split('/').pop().split('?')[0];
  if (!fichier) return defaut;
  const candidats = [];
  for (const m of html.matchAll(/https:\/\/www\.leparisien\.fr\/resizer\/[^"'\s\\]+/g)) {
    const u = m[0];
    if (u.split('/').pop().split('?')[0] !== fichier) continue;
    const t = u.match(/\/(\d+)x(\d+)\//);
    if (t && +t[1] >= 600) candidats.push({ url: u, largeur: +t[1] });
  }
  if (!candidats.length) return defaut;
  candidats.sort((a, b) => a.largeur - b.largeur);
  return candidats[0].url;
};

// Indexation des métadonnées par URL
const parLien = new Map();
pages.forEach((p, i) => {
  const cible = cibles[Math.min(i, cibles.length - 1)];
  if (!cible || cible.sentinelle) return;
  const html = typeof p.json.data === 'string' ? p.json.data : (p.json.body || '');
  if (!html || html.length < 200) return;
  parLien.set(cible.lien, {
    resume: decode(meilleureDescription(html, ['description', 'og:description', 'twitter:description'])),
    image: imageLegere(html, meta(html, ['og:image', 'twitter:image'])),
    datePubliee: meta(html, ['article:published_time', 'datePublished', 'article:modified_time']),
  });
});

// Application + re-filtrage sur la fenêtre (une date exacte peut maintenant être connue)
const maintenant = new Date();
const limite = new Date(maintenant.getTime() - cfg.fenetreJours * 86400000);

const enrichis = articles.map((a) => {
  const m = parLien.get(a.lien);
  if (!m) return a;
  if (!a.resume && m.resume) { a.resume = m.resume; }
  if (!a.image && m.image) a.image = m.image;
  if (m.datePubliee) {
    const d = new Date(m.datePubliee);
    if (!isNaN(d)) { a.date = d.toISOString(); a.dateOrigine = 'page'; }
  }
  return a;
});

const retenus = enrichis
  .filter((a) => {
    const d = new Date(a.date);
    return d >= limite && d <= new Date(maintenant.getTime() + 86400000);
  })
  .sort((a, b) => new Date(b.date) - new Date(a.date));

if (retenus.length === 0) throw new Error('Aucun article dans la fenêtre après enrichissement.');

return retenus.map((a) => ({ json: a }));

// ─── Préparation de l'appel d'embeddings (Ollama) ──────────────────────────
// Un seul appel encode tous les titres à comparer : ceux des unes des
// quotidiens, puis ceux des sources libres. L'ordre est conservé pour que
// le nœud d'appariement retrouve qui est qui.

const articles = $input.all().map((i) => i.json);
const cfg = articles[0].cfg;
const d = cfg.developpements;

// Vivier de l'appariement. Il est volontairement plus large que le nombre de
// cartes affichées : un article développé remonte dans « L'essentiel » même
// s'il ne figure pas en carte dans la section de son journal.
const parSource = new Map();
for (const a of articles.filter((x) => x.role !== 'libre')) {
  if (!parSource.has(a.source)) parSource.set(a.source, []);
  parSource.get(a.source).push(a);
}
const agenda = [];
for (const liste of parSource.values()) {
  liste.sort((a, b) => new Date(b.date) - new Date(a.date));
  const n = cfg.maxCandidatsParSource || cfg.maxUneParSource;
  let une = liste.filter((a) => a.rubrique === 'une').slice(0, n);
  if (une.length === 0) une = liste.slice(0, n);
  agenda.push(...une);
}
const libres = articles.filter((a) => a.role === 'libre');

// Rien à faire : on émet un item inerte pour que la branche reste vivante.
if (!d.actif || agenda.length === 0 || libres.length === 0) {
  return [{ json: { ignorer: true, url: `${d.ollama}/api/embed`, model: d.modeleEmbedding, input: ['-'] } }];
}

return [{
  json: {
    ignorer: false,
    url: `${d.ollama}/api/embed`,
    model: d.modeleEmbedding,
    input: [...agenda.map((a) => a.titre), ...libres.map((a) => a.titre)],
    nAgenda: agenda.length,
    nLibres: libres.length,
    liensAgenda: agenda.map((a) => a.lien),
    liensLibres: libres.map((a) => a.lien),
  },
}];

// ─── Appariement quotidiens ↔ sources libres ───────────────────────────────
// Score hybride : proximité sémantique (bge-m3) + recouvrement des noms
// propres et des chiffres du titre. Le second terme est décisif : « Saxe-Anhalt »,
// « Merz », « Colombie » distinguent deux sujets là où le sémantique seul,
// qui tasse tous les scores entre 0,68 et 0,79, ne sépare rien.

const tous = $('Fusionner les métadonnées').all().map((i) => ({ ...i.json }));
const prep = $('Préparer les embeddings').first().json;
const cfg = tous[0].cfg;
const d = cfg.developpements;

const agenda = tous.filter((a) => a.role !== 'libre');
const rendre = () => agenda.map((a) => ({ json: a }));

// Ollama injoignable, désactivé, ou réponse inexploitable → rapport sans développements
const rep = $input.first()?.json;
const vecteurs = rep?.embeddings;
if (prep.ignorer || !Array.isArray(vecteurs) || vecteurs.length !== prep.nAgenda + prep.nLibres) {
  return rendre();
}

const normer = (v) => { const n = Math.hypot(...v) || 1; return v.map((x) => x / n); };
const vAgenda = vecteurs.slice(0, prep.nAgenda).map(normer);
const vLibres = vecteurs.slice(prep.nAgenda).map(normer);
const cos = (a, b) => a.reduce((s, x, i) => s + x * b[i], 0);

// Noms propres et nombres du titre
const STOP = new Set(['Le','La','Les','Un','Une','Des','Du','Ce','Cette','Il','Elle','En','Au','Aux','Pour','Dans','Sur','Avec','Après','Avant','Comment','Pourquoi','Que','Qui','Quoi','Direct','Info','Vidéo','On','Nos','Ses','Son','Leur','Mais','Et','Ou','Plus','Tout','Tous','Ils','Elles','Selon','Face','Entre','Chez','Sans','Vers','Depuis','Quand']);
const entites = (t) => new Set(
  (String(t).match(/(?:[A-ZÀ-Ý][\wÀ-ÿ'’-]{2,})|(?:\d[\d  ,.]*\d|\d+)/g) || [])
    .map((m) => m.replace(/[’']s?$/, ''))
    .filter((m) => !STOP.has(m))
    // Une année nue n'identifie pas un sujet : « CAN 2027 » et « haute couture
    // 2026/2027 » ne parlent pas de la même chose.
    .filter((m) => !/^(?:19|20)\d{2}$/.test(m))
    .map((m) => m.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''))
);
const recouvre = (a, b) => {
  if (!a.size || !b.size) return 0;
  let i = 0; for (const x of a) if (b.has(x)) i++;
  return i / Math.min(a.size, b.size);
};

// Grilles de programmes et rendez-vous d'antenne : ce ne sont pas des articles.
const EMISSION = /^(?:le\s+)?(?:journal|jt\b|revue de presse|le supplément|l['’]invité|édition|magazine|chronique|podcast|émission|en images|en direct de|le club|débat du|les titres|à la une de)/i;
const DATE_TITRE = /\bdu\s+\d{1,2}(?:er)?\s+\w+\s+20\d{2}\s*$/i;
const estEmission = (t) => EMISSION.test(String(t).trim()) || DATE_TITRE.test(String(t).trim());

const parLien = new Map(tous.map((a) => [a.lien, a]));
const cibles = prep.liensAgenda.map((l) => parLien.get(l)).filter(Boolean);
const sources = prep.liensLibres.map((l) => parLien.get(l)).filter(Boolean);
if (cibles.length !== prep.nAgenda || sources.length !== prep.nLibres) return rendre();
const utilisable = sources.map((a) => !estEmission(a.titre));

const eCibles = cibles.map((a) => entites(a.titre));
const eSources = sources.map((a) => entites(a.titre));

const appariements = cibles.map((a, i) => {
  let best = -1, k = -1;
  for (let j = 0; j < sources.length; j++) {
    if (!utilisable[j]) continue;
    const score = d.poidsSemantique * cos(vAgenda[i], vLibres[j])
                + (1 - d.poidsSemantique) * recouvre(eCibles[i], eSources[j]);
    if (score > best) { best = score; k = j; }
  }
  return { article: a, source: sources[k], score: best };
});

// Un même article libre ne sert qu'une fois, au meilleur candidat
const pris = new Set();
let poses = 0;
for (const m of appariements.sort((x, y) => y.score - x.score)) {
  if (poses >= d.maxBlocs || m.score < d.seuil || pris.has(m.source.lien)) continue;
  pris.add(m.source.lien);
  m.article.developpement = {
    lien: m.source.lien,
    titre: m.source.titre,
    source: m.source.source,
    date: m.source.date,
    score: Math.round(m.score * 100) / 100,
    paragraphes: [],
  };
  poses++;
}

return agenda.map((a) => ({ json: a }));

// ─── Pages des sources libres à télécharger ────────────────────────────────
// Uniquement celles retenues par l'appariement. Item sentinelle si aucune,
// pour que la branche reste vivante dans n8n.

const articles = $input.all().map((i) => i.json);
const aLire = articles.filter((a) => a.developpement?.lien);

if (aLire.length === 0) {
  return [{ json: { lien: articles[0].lien, sentinelle: true } }];
}
return aLire.map((a) => ({ json: { lien: a.developpement.lien, sentinelle: false } }));

// ─── Extraction du corps des articles libres ───────────────────────────────
// Deux voies : les paragraphes de la zone <article>/<main>, sinon le champ
// articleBody du JSON-LD. Les blocs de navigation et d'abonnement sont écartés.

const articles = $('Apparier les sujets').all().map((i) => ({ ...i.json }));
const cibles = $('Préparer extraction du corps').all().map((i) => i.json);
const pages = $input.all();
const d = articles[0].cfg.developpements;

const deTag = (s) => String(s)
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"')
  .replace(/&#0?39;|&apos;/gi, '’').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n))
  .replace(/\s+/g, ' ').trim();

// Habillage éditorial à ne pas confondre avec du texte d'article
const REBUT = /^(?:s['’]abonner|abonnez|newsletter|partager|publicit|cet article|lire aussi|à lire|voir aussi|suivez|retrouvez tous|tous droits|© |commentaire|inscrivez|connectez|déjà abonné|profitez de|sans engagement|découvrez|recevez|en cliquant|vos préférences|cookies?\b|pour sauvegarder|pour profiter|vous devez être|votre compte|identifiez-vous|créez un compte|ce contenu est|activez javascript|veuillez activer)/i;
// Messages d'interface glissés au milieu du texte : lecteur vidéo bloqué,
// navigateur non pris en charge, invitation à accepter les traceurs…
const TECHNIQUE = /(?:extension de votre navigateur|lecteur (?:vid[ée]o|audio)|bloque[rz]? le chargement|regarder ce contenu|d[ée]sactiver ou la d[ée]sinstaller|votre navigateur (?:n[e’']|ne )|n[e’']est pas (?:pris en charge|compatible)|veuillez (?:accepter|activer|autoriser)|activer le javascript|acceptez les cookies|pour lire cette vid[ée]o|contenu (?:non )?disponible)/i;

// Renvois au format d'origine (vidéo, radio, émission) : ces phrases n'ont
// aucun sens dans un PDF et parasitent la lecture.
const RENVOI_MEDIA = /(?:ce texte correspond|retranscription (?:du|de la|d[e’'])|cliquez sur (?:la|le|l[e’'])|(?:la|cette) vid[ée]o ci-(?:dessus|dessous)|reportage ci-(?:dessus|dessous)|[ée]mission ci-(?:dessus|dessous)|(?:voir|revoir|regarder|[ée]couter) (?:la|le|l[e’'|’]|ci-)|extrait (?:de l[e’']|du) (?:[ée]mission|journal|reportage)|retrouvez (?:l[e’']int[ée]gralit[ée]|cette [ée]mission|le replay)|(?:disponible|à (?:revoir|r[ée][ée]couter)) (?:en replay|sur le site|dans l[e’']application)|abonnez-vous (?:à|au) (?:la newsletter|podcast)|article (?:r[ée]serv[ée]|initialement publi[ée])|mis à jour le \d)/i;
const estRebut = (t) => REBUT.test(t)
  || TECHNIQUE.test(t)
  || RENVOI_MEDIA.test(t)
  || (/\b(abonn|newsletter|cookies?|connect[ée]|inscription|javascript)\b/i.test(t) && t.length < 260);

const viaJsonLd = (html) => {
  let best = '';
  for (const m of html.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)) {
    try {
      const walk = (o) => {
        if (!o || typeof o !== 'object') return;
        if (typeof o.articleBody === 'string' && o.articleBody.length > best.length) best = o.articleBody;
        for (const v of Object.values(o)) Array.isArray(v) ? v.forEach(walk) : walk(v);
      };
      walk(JSON.parse(m[1].trim()));
    } catch (e) { /* bloc JSON-LD invalide : on passe */ }
  }
  return deTag(best);
};

const viaParagraphes = (html) => {
  const zones = [...html.matchAll(/<(article|main)\b[^>]*>([\s\S]*?)<\/\1>/gi)].map((m) => m[2]);
  const src = zones.length ? zones.sort((a, b) => b.length - a.length)[0] : html;
  const vus = new Set(); const ps = [];
  for (const m of src.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)) {
    const t = deTag(m[1]);
    if (t.length < 80 || estRebut(t)) continue;
    if (!/[.!?…»]$/.test(t) && t.length < 140) continue;   // fragment d'interface
    const k = t.slice(0, 60);
    if (vus.has(k)) continue;
    vus.add(k); ps.push(t);
  }
  return ps;
};

const corps = (html) => {
  let ps = viaParagraphes(html);
  if (ps.length < 2) {
    const ld = viaJsonLd(html);
    if (ld) ps = ld.split(/(?<=[.!?…»])\s+(?=[A-ZÀ-Ý«"])/).reduce((a, p) => {
      if (!a.length || a[a.length - 1].length > 220) a.push(p); else a[a.length - 1] += ' ' + p;
      return a;
    }, []);
  }
  const out = []; let n = 0;
  for (const p of ps) {
    if (out.length >= d.paragraphes || n + p.length > d.maxCaracteres) break;
    out.push(p); n += p.length;
  }
  return out;
};

const parLien = new Map();
pages.forEach((p, i) => {
  const cible = cibles[Math.min(i, cibles.length - 1)];
  if (!cible || cible.sentinelle) return;
  const html = typeof p.json.data === 'string' ? p.json.data : (p.json.body || '');
  if (!html || html.length < 500) return;
  const ps = corps(html);
  if (ps.length) parLien.set(cible.lien, ps);
});

// Un développement sans texte exploitable est retiré : mieux vaut rien qu'un bloc vide.
for (const a of articles) {
  if (!a.developpement) continue;
  const ps = parLien.get(a.developpement.lien);
  if (ps && ps.length) a.developpement.paragraphes = ps;
  else delete a.developpement;
}

return articles.map((a) => ({ json: a }));

// ─── Extraction et mise en valeur des données chiffrées ────────────────────
// Repère dans chaque titre/résumé : pourcentages, montants, volumes, périodes.
// Produit le texte balisé en <mark> + la liste structurée des chiffres.

const ESP = '[ \\t\\u00a0\\u202f\\u2009\\u2007]';
const NUM = `\\d{1,3}(?:${ESP}\\d{3})+(?:[.,]\\d+)?|\\d+(?:[.,]\\d+)?`;
const SIGNE = `[+\\-−–]?${ESP}*`;
const DEVISE = `€|\\$|£|¥`;
const MONNAIE_MOT = `euros?|dollars?|livres?${ESP}+sterling|francs?|yens?|centimes?`;
const ECHELLE = `milliards?|millions?|milliers`;
const UNITES = [
  'km/h','km²','km2','m²','m2','km','kg','tonnes?','litres?','hectares?','ha',
  'TWh','GWh','MWh','kWh','MW','GW','°C',
  'ans?','années?','mois','semaines?','jours?','heures?','minutes?','secondes?',
  'habitants?','personnes?','morts?','décès','blessés?','victimes?','migrants?','réfugiés?',
  'emplois?','postes?','salariés?','fonctionnaires?','chômeurs?','agents?',
  'logements?','places?','lits?','classes?','élèves?','étudiants?','enseignants?',
  'sièges?','voix','électeurs?','candidats?','députés?','sénateurs?',
  'points?','patients?','cas','entreprises?','communes?','départements?','pays','villes?',
].join('|');

// Alternation ordonnée : les motifs les plus spécifiques d'abord.
const MOTIFS = [
  `\\b(?:19|20)\\d{2}${ESP}*[-–—]${ESP}*(?:19|20)\\d{2}\\b`,                                   // 2023-2026
  `\\bde${ESP}+(?:19|20)\\d{2}${ESP}+à${ESP}+(?:19|20)\\d{2}\\b`,                              // de 2020 à 2026
  `${SIGNE}(?:${NUM})${ESP}*(?:${ECHELLE})(?:${ESP}*d(?:e|['’])${ESP}*)?(?:${MONNAIE_MOT}|${DEVISE})`, // 92 millions de dollars
  `${SIGNE}(?:${NUM})${ESP}*(?:${DEVISE})`,                                                     // 450 €
  `(?:${DEVISE})${ESP}*(?:${NUM})`,                                                             // $450
  `${SIGNE}(?:${NUM})${ESP}*(?:${MONNAIE_MOT})`,                                                // 3 000 euros
  `${SIGNE}(?:${NUM})${ESP}*(?:%|pour${ESP}?cent|points?${ESP}+de${ESP}+(?:pourcentage|base))`, // +11 %
  // « 30 milliards d'économies » : sans ce motif, seul « 30 milliards » était
  // capturé, et la carte de couverture affichait un ordre de grandeur sans
  // dire de quoi. Placé APRÈS le motif monétaire, qui reste prioritaire.
  `${SIGNE}(?:${NUM})${ESP}*(?:${ECHELLE})${ESP}*d(?:e|['’])${ESP}*\\p{L}[\\p{L}\\-]{2,}`,       // 30 milliards d'économies
  `${SIGNE}(?:${NUM})${ESP}*(?:${ECHELLE})`,                                                    // 2,5 millions
  `(?:${NUM})${ESP}*(?:${UNITES})`,                                                             // 12 000 logements
  `\\d{1,3}(?:${ESP}\\d{3})+`,                                                                  // 45 000
  `\\b\\d{4,}\\b`,                                                                              // 12500
].join('|');

const RE = new RegExp(`(?<![\\p{L}\\d.,])(?:${MOTIFS})(?![\\p{L}])`, 'giu');

const echapper = (s) =>
  String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const valeurNumerique = (t) => {
  const m = t.match(/\d{1,3}(?:[     ]\d{3})+(?:[.,]\d+)?|\d+(?:[.,]\d+)?/);
  if (!m) return null;
  let v = parseFloat(m[0].replace(/[     ]/g, '').replace(',', '.'));
  if (isNaN(v)) return null;
  if (/milliards?/i.test(t)) v *= 1e9;
  else if (/millions?/i.test(t)) v *= 1e6;
  else if (/milliers/i.test(t)) v *= 1e3;
  if (/^[\s]*[-−–]/.test(t)) v = -v;
  return v;
};

const classer = (t) => {
  if (/^\s*(?:de\s+)?(?:19|20)\d{2}\s*(?:[-–—]|à)\s*(?:19|20)\d{2}\s*$/i.test(t)) return 'periode';
  if (/%|pour\s?cent|points?\s+de\s+(?:pourcentage|base)/i.test(t)) return 'pourcentage';
  if (/[€$£¥]|euro|dollar|livre|franc|yen|centime/i.test(t)) return 'montant';
  return 'volume';
};

// Une année isolée (2026) n'est pas une donnée chiffrée : on ne la surligne pas.
const estAnneeSeule = (t) => /^\s*\d{4}\s*$/.test(t) && +t.trim() >= 1900 && +t.trim() <= 2099;

// ── Unité portée par le chiffre ────────────────────────────────────────────
// Uniquement ce que le texte source dit lui-même. Un « 30 milliards » que
// l'article laisse sans unité le reste ici : déduire « euros » d'un contexte
// budgétaire français donnerait juste le jour où l'article parlait de dollars
// ou de mètres cubes, et une revue de presse qui invente une unité est pire
// qu'une revue de presse qui n'en affiche pas. Les chiffres nus sont donc
// écartés de la couverture (ils restent surlignés dans le corps des articles).
const uniteDe = (t) => {
  const s = String(t);
  const dev = s.match(new RegExp(DEVISE));
  if (dev) return dev[0];
  const mon = s.match(new RegExp(MONNAIE_MOT, 'i'));
  if (mon) return mon[0].trim();
  if (/%|pour\s?cent|points?\s+de\s+(?:pourcentage|base)/i.test(s)) return '%';
  const u = s.match(new RegExp(`(?:${UNITES})\\s*$`, 'i'));
  if (u) return u[0].trim();
  const comp = s.match(new RegExp(`d(?:e|['’])${ESP}*(\\p{L}[\\p{L}\\-]{2,})\\s*$`, 'iu'));
  if (comp) return comp[1];
  return null;
};

const POIDS = { montant: 50, pourcentage: 42, volume: 30, periode: 8 };

function surligner(texte) {
  const trouves = [];
  if (!texte) return { html: '', chiffres: [] };
  const brutEchappe = echapper(texte);
  const html = brutEchappe.replace(RE, (brut, position) => {
    if (estAnneeSeule(brut)) return brut;
    // « à 19 heures », « dès 8 h » : c'est un horaire, pas une donnée chiffrée
    if (new RegExp(`^\\s*\\d{1,2}${ESP}*(?:h|heures?)\\s*$`, 'i').test(brut) &&
        /(?:à|vers|dès|avant|après|jusqu[’']à|depuis)\s*$/i.test(brutEchappe.slice(Math.max(0, position - 12), position))) return brut;
    const type = classer(brut);
    const valeur = valeurNumerique(brut);
    if (type === 'volume' && valeur !== null && Math.abs(valeur) < 10 && !/[a-zà-ÿ]/i.test(brut)) return brut;
    const affiche = brut.trim();
    const score = POIDS[type] + (valeur ? Math.max(0, Math.log10(Math.abs(valeur) + 1)) * 5 : 0);
    trouves.push({ texte: affiche, type, valeur, unite: uniteDe(affiche), score: Math.round(score * 10) / 10 });
    return `<mark class="chiffre chiffre--${type}">${brut}</mark>`;
  });
  return { html, chiffres: trouves };
}

// ── Application à chaque article ───────────────────────────────────────────
return $input.all().map((item) => {
  const a = item.json;
  const t = surligner(a.titre);
  const r = surligner(a.resume);

  // Les paragraphes repris d'une source libre sont surlignés eux aussi
  let dev = null;
  const chiffresDev = [];
  if (a.developpement?.paragraphes?.length) {
    const rendus = a.developpement.paragraphes.map(surligner);
    rendus.forEach((x) => chiffresDev.push(...x.chiffres));
    dev = { ...a.developpement, paragraphesHtml: rendus.map((x) => x.html) };
  }

  // Dédoublonnage des chiffres d'un même article, tri par intérêt décroissant
  const vus = new Set();
  const chiffres = [...t.chiffres, ...r.chiffres, ...chiffresDev]
    .filter((c) => {
      const k = c.texte.toLowerCase().replace(/\s+/g, ' ');
      if (vus.has(k)) return false;
      vus.add(k);
      return true;
    })
    .sort((x, y) => y.score - x.score);

  return {
    json: {
      ...a,
      titreHtml: t.html,
      resumeHtml: r.html,
      developpement: dev,
      chiffres,
      nbChiffres: chiffres.length,
      scoreChiffres: chiffres.reduce((s, c) => s + c.score, 0),
    },
  };
});

// ─── Images à télécharger ──────────────────────────────────────────────────
// Les intégrer en base64 dans le HTML rend l'impression déterministe : plus de
// requête réseau au moment du rendu, donc plus d'image manquante au hasard
// d'un délai ou d'une protection anti-hotlink.

const articles = $input.all().map((i) => i.json);
const cfg = articles[0].cfg;

// Même réduction qu'à l'affichage : inutile de rapatrier du 3000×2000.
const reduireImage = (url) => {
  if (!url) return '';
  const u = String(url);
  if (/img\.lemde\.fr/.test(u))   return u.replace(/\/\d{3,4}\/\d{3,4}\/(\d{1,3})\/(\d)\//, '/644/322/$1/$2/');
  if (/i\.f1g\.fr/.test(u))       return u.replace(/\/media\/cms\/[^/]+\//, '/media/cms/704x396_crop/');
  if (/i\.la-croix\.com/.test(u)) return u.replace(/^(https?:\/\/i\.la-croix\.com)\/[^/]+\//, '$1/620x412/');
  return u;
};

// Priorité aux articles RÉELLEMENT illustrés dans le rapport. Le plafond
// s'appliquait jusqu'ici à la simple liste chronologique : les images partaient
// aux articles les plus récents, qui finissent le plus souvent en brèves — donc
// sans visuel — et les cartes se retrouvaient sans rien. On reproduit ici la
// sélection du nœud de composition : sujets développés, puis premières cartes
// de chaque journal.
const agenda = articles.filter((a) => a.role !== 'libre');
const parJournal = new Map();
for (const a of agenda) {
  if (!parJournal.has(a.source)) parJournal.set(a.source, []);
  parJournal.get(a.source).push(a);
}
const affiches = new Set();
for (const a of agenda) if (a.developpement?.paragraphes?.length || a.developpement) affiches.add(a.lien);
for (const liste of parJournal.values()) {
  liste.sort((x, y) => new Date(y.date) - new Date(x.date));
  let une = liste.filter((x) => x.rubrique === 'une').slice(0, cfg.maxUneParSource);
  if (une.length === 0) une = liste.slice(0, cfg.maxUneParSource);
  une.forEach((x) => affiches.add(x.lien));
}

const ordonnes = [...agenda].sort((x, y) => (affiches.has(y.lien) ? 1 : 0) - (affiches.has(x.lien) ? 1 : 0));

const vues = new Set();
const liste = [];
for (const a of ordonnes) {
  if (!a.image) continue;
  const u = reduireImage(a.image);
  if (!/^https?:\/\//i.test(u) || vues.has(u)) continue;
  vues.add(u);
  liste.push({ url: u, origine: a.image });
  if (liste.length >= cfg.maxImages) break;
}

if (liste.length === 0) return [{ json: { url: '', sentinelle: true } }];
return liste.map((x) => ({ json: { ...x, sentinelle: false } }));

// ─── Intégration des images en base64 ──────────────────────────────────────
// Chaque image rapatriée devient une URL « data: ». Une image absente est
// simplement retirée de l'article : mieux vaut pas de visuel qu'un cadre vide.

const articles = $('Extraire et surligner les chiffres').all().map((i) => ({ ...i.json }));
const cibles = $('Préparer les images').all().map((i) => i.json);
const recues = $input.all();

const parUrl = new Map();
for (let i = 0; i < recues.length; i++) {
  const cible = cibles[i];
  if (!cible || cible.sentinelle) continue;
  const bin = recues[i].binary?.data;
  if (!bin) continue;
  const type = String(bin.mimeType || '');
  if (!/^image\//i.test(type)) continue;
  let buf = null;
  try { buf = await this.helpers.getBinaryDataBuffer(i, 'data'); } catch (e) { /* voir repli */ }
  if (!buf && typeof bin.data === 'string' && bin.data.length > 256) buf = Buffer.from(bin.data, 'base64');
  if (!buf || buf.length < 512) continue;                 // réponse vide ou pixel de suivi
  parUrl.set(cible.origine, `data:${type};base64,${buf.toString('base64')}`);
}

let integrees = 0, retirees = 0;
for (const a of articles) {
  if (!a.image) continue;
  const d = parUrl.get(a.image);
  if (d) { a.image = d; integrees++; }
  else { a.image = ''; retirees++; }
}

return articles.map((a, i) => ({
  json: i === 0 ? { ...a, imagesIntegrees: integrees, imagesRetirees: retirees } : a,
}));

// ─── Contrôle qualité : passe déterministe, puis préparation du jugement ───
// Ce qui se vérifie sûrement se vérifie ici : coupures de texte, longueurs
// aberrantes, résumé recopiant le titre. Le modèle local n'est sollicité que
// pour ce qu'une règle ne sait pas trancher.

const articles = $input.all().map((i) => ({ ...i.json }));
const cfg = articles[0].cfg;
const q = cfg.controleQualite || { actif: false };

const rapport = { coupures: 0, tropCourts: 0, resumesRecopies: 0, soumisAuModele: 0 };

const finiCorrectement = (t) => /[.!?…»"'\)]\s*$/.test(String(t).trim());
const normal = (t) => String(t || '').toLowerCase().replace(/[^a-zà-ÿ0-9]+/g, ' ').trim();

for (const a of articles) {
  // Un résumé qui recopie le titre n'apporte rien.
  if (a.resume && normal(a.resume) === normal(a.titre)) { a.resume = ''; a.resumeHtml = ''; rapport.resumesRecopies++; }

  // Filet de sécurité : si un résumé reste coupé en plein mot malgré le choix
  // de la meilleure balise, on le ramène à sa dernière phrase complète plutôt
  // que de laisser « …sur Aryna Sabalenk » à l'impression.
  if (a.resume && !finiCorrectement(a.resume)) {
    const phrases = a.resume.match(/[^.!?…»]+[.!?…»]+/g);
    const recolle = phrases ? phrases.join('').trim() : '';
    if (recolle.length >= 60) {
      const retire = a.resume.slice(recolle.length).trim();
      a.resume = recolle;
      if (a.resumeHtml && retire) {
        const i = a.resumeHtml.replace(/<[^>]+>/g, '').indexOf(retire);
        if (i > 0) a.resumeHtml = a.resumeHtml.slice(0, a.resumeHtml.length - retire.length).trim();
      }
      rapport.resumesTronques = (rapport.resumesTronques || 0) + 1;
    }
  }

  const d = a.developpement;
  if (!d?.paragraphesHtml?.length) continue;
  const gardes = [];
  d.paragraphesHtml.forEach((h, i) => {
    const texte = String(h).replace(/<[^>]+>/g, '').trim();
    if (texte.length < 60) { rapport.tropCourts++; return; }
    // Une phrase tronquée en pleine course est le défaut le plus visible.
    if (!finiCorrectement(texte)) { rapport.coupures++; return; }
    gardes.push({ html: h, texte });
  });
  d.paragraphesHtml = gardes.map((g) => g.html);
  d.textesPourControle = gardes.map((g) => g.texte);
  if (!d.paragraphesHtml.length) delete a.developpement;
}

// ── Constitution des lots pour le modèle ───────────────────────────────────
const aJuger = [];
for (const a of articles) {
  (a.developpement?.textesPourControle || []).forEach((t, i) => {
    aJuger.push({ lien: a.lien, index: i, texte: t });
  });
}
rapport.soumisAuModele = aJuger.length;

const lots = [];
if (!q.actif || aJuger.length === 0) {
  lots.push({ ignorer: true, url: `${q.ollama}/api/generate`, model: q.modele, prompt: '.', rapport });
}

const consigne = `Tu contrôles la qualité d'une revue de presse. Pour chaque paragraphe, dis s'il s'agit de texte d'article publiable.

Rejette : les renvois au format d'origine (vidéo, replay, émission, « cliquez sur »), les menus et boutons de partage, les mentions d'abonnement ou de cookies, les phrases sans information.
Garde : toute phrase d'information, même courte.

Réponds UNIQUEMENT par un tableau JSON, un objet par paragraphe, dans l'ordre :
[{"i":0,"garder":true},{"i":1,"garder":false}]`;

for (let i = 0; q.actif && i < aJuger.length && lots.length < q.maxLots; i += q.tailleLot) {
  const lot = aJuger.slice(i, i + q.tailleLot);
  lots.push({
    ignorer: false,
    url: `${q.ollama}/api/generate`,
    model: q.modele,
    prompt: `${consigne}\n\n${lot.map((x, k) => `[${k}] ${x.texte}`).join('\n\n')}`,
    cles: lot.map((x) => ({ lien: x.lien, index: x.index })),
    rapport: lots.length === 0 ? rapport : undefined,
    tache: 'paragraphes',
  });
}
// ── Étiquettes des temps forts ─────────────────────────────────────────────
// Une règle ne sait pas distinguer un thème d'une citation : « Ils sont où,
// les 30 milliards ? : censure… » donnait l'étiquette « ILS SONT OÙ, LES 30
// MILLIARDS ». Le modèle, lui, sait résumer un sujet en deux ou trois mots.
const pourEtiquettes = articles
  .filter((a) => a.developpement?.paragraphesHtml?.length)
  .slice(0, 8);

if (pourEtiquettes.length) {
  const consigneEtiq = `Pour chaque titre de presse, donne le THÈME en 2 à 4 mots, en majuscules, sans ponctuation.
Le thème est le sujet traité, jamais un extrait de citation.
N'emploie QUE des mots présents dans le titre, recopiés à l'identique. N'invente aucun mot.

Exemples :
« Ils sont où, les 30 milliards d'euros d'économies ? » : la tension monte avant le budget → BUDGET 2027
"Nous devons réduire la vitesse" : le patron d'Anthropic appelle à ralentir l'IA → RÉGULATION DE L'IA
Législatives en Suède : la droite nationaliste en tête → LÉGISLATIVES SUÉDOISES

Réponds UNIQUEMENT par un tableau JSON, dans l'ordre :
[{"i":0,"theme":"BUDGET 2027"},{"i":1,"theme":"..."}]`;

  lots.push({
    ignorer: false,
    tache: 'etiquettes',
    url: `${q.ollama}/api/generate`,
    model: q.modeleEtiquettes || q.modele,
    prompt: `${consigneEtiq}\n\n${pourEtiquettes.map((a, k) => `[${k}] ${a.titre}`).join('\n')}`,
    liens: pourEtiquettes.map((a) => a.lien),
    titres: pourEtiquettes.map((a) => a.titre),
  });
}

return lots.map((l) => ({ json: l }));

// ─── Application du jugement du modèle ─────────────────────────────────────
// Les paragraphes rejetés sont retirés. Un développement vidé de sa substance
// est supprimé : mieux vaut pas de développement qu'un bloc incohérent.
// Modèle injoignable ou réponse illisible → seule la passe déterministe
// s'applique, le rapport est produit quand même.

const articles = $('Intégrer les images').all().map((i) => ({ ...i.json }));
const prepares = $('Préparer le contrôle qualité').all().map((i) => i.json);
const reponses = $input.all();

const rapport = prepares.find((p) => p.rapport)?.rapport
  || { coupures: 0, tropCourts: 0, resumesRecopies: 0, soumisAuModele: 0 };
rapport.rejetesParModele = 0;
rapport.modeleConsulte = false;

const aRetirer = new Set();
const etiquettes = new Map();

reponses.forEach((rep, i) => {
  const prep = prepares[i];
  if (!prep || prep.ignorer) return;

  // Lot d'étiquettes : thème court de chaque temps fort.
  if (prep.tache === 'etiquettes') {
    const brut = rep.json?.response;
    if (typeof brut !== 'string') return;
    const m = brut.match(/\[[\s\S]*\]/);
    if (!m) return;
    try {
      JSON.parse(m[0]).forEach((v) => {
        const lien = prep.liens?.[v.i];
        const theme = String(v.theme || '').trim().replace(/[.«»"']/g, '');
        if (!lien || !theme || theme.length > 40) return;
        // Garde-fou : le modèle invente parfois des mots (« SOVEREIGNETE »,
        // « SUEDIQUE »). Une étiquette mal orthographiée est pire qu'une
        // étiquette médiocre : on exige que chaque mot vienne du titre.
        const titre = prep.titres?.[v.i] || '';
        const norm = (t) => String(t).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
        const dansTitre = norm(titre);
        const inventes = norm(theme).split(/[^a-z0-9]+/)
          .filter((mot) => mot.length >= 4 && !dansTitre.includes(mot.slice(0, Math.max(4, mot.length - 2))));
        if (inventes.length) { rapport.etiquettesRejetees = (rapport.etiquettesRejetees || 0) + 1; return; }

        // Aucun de ces modèles ne restitue les accents : « DERAILLEMENT »,
        // « SUEDE ». Puisque chaque mot vient du titre, on y reprend son
        // orthographe exacte — le modèle choisit, la source corrige.
        const motsTitre = String(titre).match(/[\wÀ-ÿ'’-]+/g) || [];
        const accentue = theme.split(/(\s+)/).map((mot) => {
          if (/^\s+$/.test(mot) || mot.length < 3) return mot;
          const cible = norm(mot);
          const trouve = motsTitre.find((w) => norm(w) === cible);
          return trouve ? trouve.toUpperCase() : mot;
        }).join('');
        etiquettes.set(lien, accentue.toUpperCase());
      });
      rapport.etiquettesGenerees = etiquettes.size;
    } catch (e) { /* réponse illisible : étiquette heuristique conservée */ }
    return;
  }

  if (!prep.cles) return;
  const brut = rep.json?.response;
  if (typeof brut !== 'string') return;
  const m = brut.match(/\[[\s\S]*\]/);
  if (!m) return;
  let verdicts;
  try { verdicts = JSON.parse(m[0]); } catch (e) { return; }
  if (!Array.isArray(verdicts)) return;
  rapport.modeleConsulte = true;
  verdicts.forEach((v) => {
    const cle = prep.cles[v.i];
    if (!cle) return;
    if (v.garder === false) { aRetirer.add(cle.lien + '#' + cle.index); rapport.rejetesParModele++; }
  });
});

let devSupprimes = 0;
for (const a of articles) {
  const d = a.developpement;
  if (!d?.paragraphesHtml?.length) continue;
  const gardes = d.paragraphesHtml.filter((_, i) => !aRetirer.has(a.lien + '#' + i));
  if (gardes.length === 0) { delete a.developpement; devSupprimes++; continue; }
  d.paragraphesHtml = gardes;
  delete d.textesPourControle;
}

for (const a of articles) {
  const e = etiquettes.get(a.lien);
  if (e) a.etiquetteIA = e;
}
rapport.developpementsSupprimes = devSupprimes;
rapport.developpementsRestants = articles.filter((a) => a.developpement?.paragraphesHtml?.length).length;

return articles.map((a, i) => ({ json: i === 0 ? { ...a, controleQualite: rapport } : a }));

// ─── Composition du rapport HTML (converti en PDF à l'étape suivante) ──────

// Schéma du workflow, injecté à la construction du JSON par build.mjs :
// il décrit les nœuds réellement présents et ne peut donc pas diverger.
const SCHEMA = [{"titre":"Déclenchement","noeuds":[{"nom":"Toutes les 3 jours à 8 h","role":"Déclencheur interne, inactif : c’est launchd qui commande."},{"nom":"Test manuel","role":"Permet de produire un rapport à la demande."},{"nom":"Lire l’état précédent","role":"Date du dernier envoi et liens déjà expédiés."},{"nom":"Configuration","role":"Destinataires, fenêtre de collecte, seuils, plafonds."}]},{"titre":"Collecte","noeuds":[{"nom":"Liste des flux","role":"21 flux RSS : 9 quotidiens, 12 sources libres."},{"nom":"Récupérer les flux","role":"Téléchargement, 3 en parallèle, tolérant aux pannes."},{"nom":"Parser le XML","role":"Conversion en données exploitables."},{"nom":"Normaliser les articles","role":"Journal déduit du domaine, datation, dédoublonnage, fenêtre de 3 jours."}]},{"titre":"Enrichissement","noeuds":[{"nom":"Préparer enrichissement","role":"Repère les articles sans résumé — Le Parisien n’en fournit aucun."},{"nom":"Récupérer les pages","role":"Lecture des balises <meta> publiques."},{"nom":"Fusionner les métadonnées","role":"Complète résumé, image et date exacte."}]},{"titre":"Rapprochement des sujets","noeuds":[{"nom":"Préparer les embeddings","role":"Rassemble les titres à comparer."},{"nom":"Encoder les titres (Ollama)","role":"bge-m3, local : transforme chaque titre en vecteur."},{"nom":"Apparier les sujets","role":"Sémantique + noms propres partagés : 8 % d’appariement en lexical seul, ~55 % ainsi."}]},{"titre":"Développement","noeuds":[{"nom":"Préparer extraction du corps","role":"Liste les articles libres à lire."},{"nom":"Récupérer les articles libres","role":"France Info, France 24, RFI, Euronews — texte intégral accessible."},{"nom":"Extraire le corps","role":"Paragraphes de l’article, habillage éditorial écarté."}]},{"titre":"Analyse et visuels","noeuds":[{"nom":"Extraire et surligner les chiffres","role":"Pourcentages, montants, volumes, périodes, avec l’unité que porte le texte source."},{"nom":"Préparer les images","role":"Visuels à rapatrier, en version réduite."},{"nom":"Récupérer les images","role":"Téléchargement des visuels."},{"nom":"Intégrer les images","role":"Conversion en base64 : aucune requête réseau à l’impression."}]},{"titre":"Contrôle qualité","noeuds":[{"nom":"Préparer le contrôle qualité","role":"Détecte coupures, longueurs aberrantes, résumés recopiés."},{"nom":"Juger la qualité (Ollama)","role":"gemma2:9b, local : écarte parasites et phrases sans information."},{"nom":"Appliquer le contrôle qualité","role":"Retire le rejeté ; llama3.1:8b rédige les thèmes, vérifiés sur le titre."}]},{"titre":"Mise en page et PDF","noeuds":[{"nom":"Composer le rapport HTML","role":"Mise en page A4, plus une variante sans images."},{"nom":"Convertir en PDF (Gotenberg)","role":"Chromium sans interface, en conteneur."},{"nom":"Compresser le PDF","role":"Ghostscript 300 dpi, au-delà de 6 Mo seulement. Conversion sRGB : sans elle, Aperçu n’affiche pas les photos."},{"nom":"Vérifier la taille du PDF","role":"Au-delà de 20 Mo, bascule sur la version sans images."},{"nom":"PDF trop lourd ?","role":"Aiguillage vers le repli."},{"nom":"Basculer sur la version allégée","role":"Reprend le HTML sans visuels."},{"nom":"Convertir en PDF (version allégée)","role":"Second passage, texte seul."}]},{"titre":"Diffusion","noeuds":[{"nom":"Préparer l’envoi","role":"Nomme le PDF et compose le corps du message."},{"nom":"Enregistrer le PDF","role":"Archivage dans rapports/."},{"nom":"Mémoriser l’état","role":"Note la date et les liens de ce rapport."},{"nom":"Écrire l’état","role":"Sauvegarde pour l’exécution suivante."},{"nom":"Envoyer le rapport","role":"Expédition par SMTP, PDF en pièce jointe."}]}];

// Les neuf étapes sont réparties en quatre couloirs de lecture.
// Palette « Nordique » : bleu-gris, sauge, sable, argile. Désaturée et froide,
// délibérément éloignée de l'ambre, du vert, du bleu et du violet réservés
// aux types de données chiffrées — aucune confusion possible entre les deux.
const GROUPES = [
  { num: '01', titre: 'Collecte', sous: 'Ce que la presse publie', couleur: '#4a6572', etapes: ['Déclenchement', 'Collecte', 'Enrichissement'] },
  { num: '02', titre: 'Rapprochement', sous: 'Relier les sujets entre eux', couleur: '#7d9b8a', etapes: ['Rapprochement des sujets', 'Développement'] },
  { num: '03', titre: 'Analyse', sous: 'Extraire et vérifier', couleur: '#c2a878', etapes: ['Analyse et visuels', 'Contrôle qualité'] },
  { num: '04', titre: 'Fabrication', sous: 'Composer puis diffuser', couleur: '#9b6a62', etapes: ['Mise en page et PDF', 'Diffusion'] },
];
const LANES = GROUPES.map((g) => ({
  ...g,
  etapes: g.etapes.map((t) => SCHEMA.find((e) => e.titre === t)).filter(Boolean),
})).filter((g) => g.etapes.length);

const articles = $input.all().map((i) => i.json);
const cfg = articles[0].cfg;
const ORDRE = ['Le Monde', 'Le Figaro', 'Le Parisien', 'Libération', 'La Croix'];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const MOIS = ['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
const jourLong = (d) => `${d.getDate()} ${MOIS[d.getMonth()]} ${d.getFullYear()}`;
const jourCourt = (d) => `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}`;
const heure = (d) => `${String(d.getHours()).padStart(2,'0')}h${String(d.getMinutes()).padStart(2,'0')}`;

const dates = articles.map((a) => new Date(a.date)).sort((a, b) => a - b);
const debut = dates[0], fin = dates[dates.length - 1];
const periode = debut.toDateString() === fin.toDateString()
  ? `du ${jourLong(fin)}`
  : `du ${debut.getDate()} ${debut.getMonth() === fin.getMonth() ? '' : MOIS[debut.getMonth()] + ' '}au ${jourLong(fin)}`;

// ── Sujets couverts par plusieurs journaux ─────────────────────────────────
const VIDES = new Set(['dans','pour','avec','plus','sans','sous','leur','leurs','cette','cet','les','des','une','aux','que','qui','quoi','mais','donc','elle','elles','ils','son','sea','ses','est','sont','être','avoir','fait','faire','après','avant','entre','vers','chez','contre','tout','tous','toute','toutes','comme','encore','déjà','très','bien','peut','veut','face','selon','direct','notre','votre','nouvelle','nouveau','ans']);
const jetons = (t) => new Set(
  t.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
   .replace(/[^a-z0-9]+/g, ' ').split(' ')
   .filter((m) => m.length >= 4 && !VIDES.has(m))
);
const jaccard = (a, b) => {
  let inter = 0;
  for (const x of a) if (b.has(x)) inter++;
  return inter / (a.size + b.size - inter || 1);
};
const avecJetons = articles.map((a) => ({ a, j: jetons(a.titre) }));
const utilises = new Set();
const sujets = [];
for (let i = 0; i < avecJetons.length; i++) {
  if (utilises.has(i)) continue;
  const groupe = [i];
  for (let k = i + 1; k < avecJetons.length; k++) {
    if (utilises.has(k)) continue;
    if (avecJetons[k].a.source === avecJetons[i].a.source) continue;
    if (jaccard(avecJetons[i].j, avecJetons[k].j) >= cfg.seuilSujetCommun) { groupe.push(k); utilises.add(k); }
  }
  if (groupe.length > 1) { groupe.forEach((g) => utilises.add(g)); sujets.push(groupe.map((g) => avecJetons[g].a)); }
}
sujets.sort((x, y) => y.length - x.length);

// ── Chiffres marquants (toutes sources confondues) ─────────────────────────
const vus = new Set();
const chiffresCles = articles
  .flatMap((a) => (a.chiffres || []).map((c) => ({ ...c, article: a })))
  .sort((x, y) => y.score - x.score)
  .filter((c) => {
    const k = c.texte.toLowerCase().replace(/\s+/g, ' ');
    // Un chiffre sans unité ne dit rien en couverture : « 12 millions » de
    // quoi ? L'unité est calculée par le nœud d'extraction, seul à voir le
    // texte source — la décider ici en parallèle serait la faire diverger.
    if (vus.has(k) || c.type === 'periode' || !c.unite) return false;
    vus.add(k); return true;
  })
  .slice(0, cfg.maxChiffresMarquants);

// ── Importance d'un article ────────────────────────────────────────────────
// Trois signaux, par ordre de poids : un développement rédigé à partir d'une
// source libre, une couverture par plusieurs quotidiens, et la densité de
// données chiffrées.
const dansSujet = new Map();
sujets.forEach((groupe, i) => groupe.forEach((a) => dansSujet.set(a.lien, { rang: i, taille: groupe.length })));

const importance = (a) => {
  let n = 0;
  if (a.developpement?.paragraphesHtml?.length) n += 100 + (a.developpement.score || 0) * 20;
  const g = dansSujet.get(a.lien);
  if (g) n += 40 * (g.taille - 1);
  n += Math.min(a.scoreChiffres || 0, 60) / 2;
  if (a.rubrique === 'une') n += 15;
  if (/^\s*(?:EN DIRECT|EN IMAGES|DIRECT)\b/i.test(a.titre)) n -= 30;
  return n;
};

// Entrent dans « L'essentiel » les sujets développés et ceux traités par
// plusieurs titres : ce sont les seuls dont l'importance est établie par un
// fait, pas par une heuristique.
const aDev = (a) => (a.developpement?.paragraphesHtml?.length ? 1 : 0);

// Un même événement traité par cinq quotidiens ne doit occuper qu'une entrée :
// on retient le meilleur article et on signale les autres titres.
const candidats = articles
  .filter((a) => aDev(a) || dansSujet.has(a.lien))
  .sort((x, y) => aDev(y) - aDev(x) || importance(y) - importance(x));

// Deux titres qui partagent au moins deux noms propres marquants parlent du
// même événement, même s'ils n'ont presque aucun mot commun par ailleurs
// (« cordon sanitaire » et « onde de choc » autour de « Saxe-Anhalt »).
const MOTS_COURANTS = new Set(['France','Paris','Europe','Allemagne','Etats','Unis','Monde','Figaro','Croix','Parisien','Direct','Info']);
const nomsPropres = (t) => {
  const sortie = new Set();
  for (const brut of String(t).match(/[A-ZÀ-Ý][\wÀ-ÿ'’-]{3,}/g) || []) {
    const m = brut.replace(/[’']s?$/, '');
    if (MOTS_COURANTS.has(m)) continue;
    const norm = (x) => x.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
    sortie.add(norm(m));
    // « Saxe-Anhalt » vaut aussi « saxe » et « anhalt » : sans cela un nom
    // composé ne pèse qu'une unité et deux titres sur le même lieu ne se
    // rapprochent pas.
    if (m.includes('-')) m.split('-').filter((x) => x.length >= 4).forEach((x) => sortie.add(norm(x)));
  }
  return sortie;
};
const communs = (a, b) => { let n = 0; for (const x of a) if (b.has(x)) n++; return n; };

const essentiel = [];
const jetonsGardes = [];
let sansDev = 0;
for (const a of candidats) {
  if (essentiel.length >= cfg.maxEssentiel) break;
  // Les sujets sans développement ne doivent pas noyer les autres.
  if (!aDev(a) && sansDev >= cfg.maxEssentielSansDev) continue;
  const ja = jetons(a.titre);
  const groupe = dansSujet.get(a.lien);
  const na = nomsPropres(a.titre);
  let i = jetonsGardes.findIndex((g) =>
    (groupe && g.groupe && g.groupe.rang === groupe.rang)
    || jaccard(ja, g.jetons) >= 0.30
    || communs(na, g.noms) >= 2);
  if (i >= 0) {
    // Même sujet : on garde l'angle de ce journal plutôt qu'un simple nom.
    const d = essentiel[i];
    if (d.source !== a.source && !d.angles.some((x) => x.source === a.source)) {
      d.angles.push({
        source: a.source, couleur: a.couleur, lien: a.lien,
        titreHtml: a.titreHtml, resumeHtml: a.resumeHtml,
      });
    }
    continue;
  }
  essentiel.push({ ...a, angles: [] });
  if (!aDev(a)) sansDev++;
  jetonsGardes.push({ jetons: ja, groupe, noms: na });
}
const nbDeveloppes = essentiel.filter(aDev).length;

// Deux niveaux : les sujets majeurs (développés, souvent repris par plusieurs
// titres) passent en grand format ; les autres suivent en format compact.
const tempsForts = essentiel.filter(aDev).slice(0, cfg.maxTempsForts);
const cleForts = new Set(tempsForts.map((a) => a.lien));
const reste = essentiel.filter((a) => !cleForts.has(a.lien));
// On exclut des sections journal l'article retenu ET ses doublons de sujet.
const dansEssentiel = new Set();
essentiel.forEach((e) => {
  dansEssentiel.add(e.lien);
  const je = jetons(e.titre);
  const ge = dansSujet.get(e.lien);
  for (const a of candidats) {
    const ga = dansSujet.get(a.lien);
    if ((ge && ga && ge.rang === ga.rang)
        || jaccard(je, jetons(a.titre)) >= 0.30
        || communs(nomsPropres(e.titre), nomsPropres(a.titre)) >= 2) dansEssentiel.add(a.lien);
  }
});

// ── Regroupement par journal ───────────────────────────────────────────────
const parSource = new Map();
for (const a of articles) {
  if (!parSource.has(a.source)) parSource.set(a.source, []);
  parSource.get(a.source).push(a);
}
const journaux = ORDRE.filter((s) => parSource.has(s)).map((s) => {
  const liste = parSource.get(s).sort((a, b) => new Date(b.date) - new Date(a.date));
  // Un journal dont le flux « une » n'est pas exploitable (Le Parisien ne publie
  // que des archives) mettrait sinon zéro article en avant : on prend les plus récents.
  // Les articles déjà traités dans « L'essentiel » ne sont pas repris ici.
  const restants = liste.filter((a) => !dansEssentiel.has(a.lien));
  let une = restants.filter((a) => a.rubrique === 'une').slice(0, cfg.maxUneParSource);
  if (une.length === 0) une = restants.slice(0, cfg.maxUneParSource);
  // Les articles développés d'abord, puis les autres : le lecteur trouve la
  // matière en haut de section, les sujets secondaires en dessous puis en bref.
  // Les directs (« EN DIRECT… ») sont des pages mouvantes, souvent périmées à
  // la lecture : ils restent présents mais passent après les articles fermés.
  const estDirect = (a) => /^\s*(?:EN DIRECT|EN IMAGES|DIRECT)\b/i.test(a.titre);
  une.sort((a, b) => {
    const da = a.developpement?.paragraphesHtml?.length ? 1 : 0;
    const db = b.developpement?.paragraphesHtml?.length ? 1 : 0;
    if (da !== db) return db - da;
    const la = estDirect(a) ? 1 : 0, lb = estDirect(b) ? 1 : 0;
    if (la !== lb) return la - lb;
    return new Date(b.date) - new Date(a.date);
  });
  const cleUne = new Set(une.map((a) => a.lien));
  return {
    source: s, couleur: liste[0].couleur, total: liste.length, une,
    breves: restants.filter((a) => !cleUne.has(a.lien)).slice(0, cfg.maxBrevesParSource),
    dansEssentiel: liste.filter((a) => dansEssentiel.has(a.lien)).length,
  };
});

// ── Réduction des images à la source ───────────────────────────────────────
// Les CDN des journaux acceptent une taille dans l'URL : on demande une version
// légère, sinon le PDF atteint des dizaines de Mo (images en pleine résolution).
const reduireImage = (url) => {
  if (!url) return '';
  if (String(url).startsWith('data:')) return url;   // déjà intégrée
  try {
    const u = String(url);
    if (/img\.lemde\.fr/.test(u))      return u.replace(/\/\d{3,4}\/\d{3,4}\/(\d{1,3})\/(\d)\//, '/644/322/$1/$2/');
    if (/i\.f1g\.fr/.test(u))          return u.replace(/\/media\/cms\/[^/]+\//, '/media/cms/704x396_crop/');
    if (/i\.la-croix\.com/.test(u))    return u.replace(/^(https?:\/\/i\.la-croix\.com)\/[^/]+\//, '$1/620x412/');
    return u;  // Le Parisien signe ses URL de redimensionnement : on n'y touche pas
  } catch (e) { return String(url); }
};

// Coupe au dernier mot entier : « …la tension monte à l'appr... » devenait
// illisible, la troncature brutale cassant le mot en cours.
const couper = (t, max) => {
  let p = String(t || '').trim().replace(/\s+/g, ' ');
  // Un guillemet ouvrant retiré laissait son fermant orphelin au milieu du texte.
  if (/^[«"“]/.test(p)) p = p.replace(/^[«"“]\s*/, '').replace(/\s*[»"”]\s*(?=[:,;]|$)/, ' ');
  p = p.replace(/\s+/g, ' ').trim();
  if (p.length <= max) return p;
  const bout = p.slice(0, max);
  const esp = bout.lastIndexOf(' ');
  return (esp > max * 0.5 ? bout.slice(0, esp) : bout).replace(/[,;:–—-]$/, '') + '…';
};

// Étiquette courte d'un sujet : ce qui précède les deux-points fait
// généralement office de thème dans la titraille de presse.
const etiquette = (titre) => {
  let t = String(titre || '').replace(/^(?:EN DIRECT|EN IMAGES|DIRECT|INFO [A-ZÀ-Ý ]+)[,:\s-]+/i, '').trim();

  // Un titre ouvrant sur une citation ne dit pas son thème avant les
  // deux-points : « Nous devons réduire la vitesse » : le patron d'Anthropic…
  const citation = t.match(/^[«"“][^»"”]{3,}[»"”]\s*[:,]\s*(.+)$/);
  if (citation) t = citation[1].trim();
  t = t.replace(/^[«"“”\s]+/, '');

  const avantDeuxPoints = (t.match(/^([^:«»]{4,40})\s*:/) || [])[1];

  // Les noms propres et les millésimes désignent le sujet mieux qu'un début
  // de phrase : « Pour sa quatrième campagne, Marine Le Pen se repose… »
  // donne MARINE LE PEN, là où la découpe mécanique donnait POUR SA QUATRIÈME.
  const COURANTS = new Set(['Le','La','Les','Un','Une','Des','Du','De','Ce','Il','Elle','En','Au','Aux','Pour','Dans','Sur','Avec','Après','Avant','Comment','Pourquoi','Que','Qui','Mais','Et','Ou','Plus','Tout','Tous','Selon','Face','Entre','Chez','Sans','Vers','Depuis','Quand','Son','Sa','Ses','Leur','Nos','Notre','Cette']);
  const propres = [];
  // Le mot enchaîné peut être court (« Marine Le Pen ») : une seule lettre suffit.
  for (const m of t.matchAll(/[A-ZÀ-Ý][\wÀ-ÿ'’-]{2,}(?:\s+[A-ZÀ-Ý][\wÀ-ÿ'’-]+)*|\b(?:19|20)\d{2}\b/g)) {
    // Les mots courants ne sont retirés qu'en TÊTE de bloc : « Marine Le Pen »
    // deviendrait sinon « Marine Pen ».
    const mots = m[0].split(/\s+/);
    while (mots.length && COURANTS.has(mots[0])) mots.shift();
    while (mots.length && COURANTS.has(mots[mots.length - 1])) mots.pop();
    const bloc = mots.join(' ');
    // Le premier mot d'un titre est capitalisé par convention, pas parce qu'il
    // s'agit d'un nom propre : « Réaffirmer la souveraineté… » donnait
    // RÉAFFIRMER. On écarte un mot isolé en tête qui a une forme verbale.
    const enTete = m.index === 0;
    const verbal = /(?:er|ir|re|ant|ait|ent|ez|ons)$/i.test(bloc) && !/\s/.test(bloc);
    if (bloc.length >= 3 && !(enTete && verbal)) propres.push(bloc);
  }

  const aDuFond = (x) => x && /[A-ZÀ-Ý0-9]/.test(x.slice(1)) === false
    ? propres.some((n) => x.includes(n)) : true;

  // On garde la découpe avant deux-points si elle porte un nom propre ou un
  // nombre ; sinon on préfère les noms propres du titre.
  if (avantDeuxPoints && /[A-ZÀ-Ý][\wÀ-ÿ]|\d/.test(avantDeuxPoints.slice(1))) {
    return couper(avantDeuxPoints.trim(), 26).replace(/…$/, '').toUpperCase();
  }
  if (propres.length) {
    // On n'assemble que des noms ENTIERS : couper à 26 caractères donnait
    // « MARK CARNEY EMMANUEL », le second nom tranché en plein milieu.
    const retenus = [];
    for (const n of propres) {
      const essai = [...retenus, n].join(' ');
      if (essai.length > 26) break;
      retenus.push(n);
    }
    // Un sigle isolé ne fait pas un thème : « TER » seul n'apprend rien.
    // Sous six caractères, la découpe avant deux-points est plus parlante.
    const assemble = retenus.join(' ');
    if (assemble.length >= 6) return assemble.toUpperCase();
    if (avantDeuxPoints) return couper(avantDeuxPoints.trim(), 26).replace(/…$/, '').toUpperCase();
    if (assemble) return assemble.toUpperCase();
    return couper(propres[0], 26).replace(/…$/, '').toUpperCase();
  }
  if (avantDeuxPoints) return couper(avantDeuxPoints.trim(), 24).replace(/…$/, '').toUpperCase();
  return couper(t, 24).replace(/…$/, '').replace(/\s+\S{1,3}$/, '').toUpperCase();
};

// Ce qu'on retient du sujet : le chiffre marquant s'il existe, sinon la
// suite du titre.
const accroche = (a) => {
  const c = (a.chiffres || []).find((x) => x.type !== 'periode');
  if (c) return c.texte;
  const apres = String(a.titre).split(/\s*:\s*/).slice(1).join(' : ');
  return couper(apres || a.titre, 46);
};

// ── Fragments HTML ─────────────────────────────────────────────────────────
const puces = (a) => (a.chiffres || []).slice(0, 4)
  .map((c) => `<span class="puce puce--${c.type}">${esc(c.texte)}</span>`).join('');

// Le bloc porte le titre de l'article source, jamais celui de l'article du
// quotidien : un rapprochement erroné se voit alors immédiatement, au lieu
// d'attribuer un texte au mauvais sujet.
const blocDeveloppement = (a) => {
  const d = a.developpement;
  if (!d?.paragraphesHtml?.length) return '';
  return `
    <div class="dev">
      <div class="dev-chapeau">Développement · ${esc(d.source)}</div>
      <div class="dev-titre">${esc(d.titre)}</div>
      ${d.paragraphesHtml.map((p) => `<p class="dev-texte">${p}</p>`).join('')}
    </div>`;
};

// Un même événement vu par plusieurs rédactions : on juxtapose leurs titres et
// leurs chapôs tels quels. Ce sont leurs angles, dans leurs mots, attribuables.
// Réservé aux temps forts : dans « L'essentiel », format compact, ce bloc
// alourdissait la lecture sans être attendu.
const blocAngles = (a) => {
  if (!a.angles?.length) return '';
  return `
    <div class="angles">
      <div class="angles-titre">Le même sujet vu par ${a.angles.length} autre${a.angles.length > 1 ? 's' : ''} titre${a.angles.length > 1 ? 's' : ''}</div>
      ${a.angles.map((x) => `
        <div class="angle">
          <span class="tag" style="background:${x.couleur}">${esc(x.source)}</span>
          <div class="angle-corps">
            <div class="angle-titre">${x.titreHtml}</div>
            ${x.resumeHtml ? `<div class="angle-resume">${x.resumeHtml}</div>` : ''}
          </div>
        </div>`).join('')}
    </div>`;
};

const carteFort = (a) => `
  <article class="fort">
    ${a.image ? `<div class="fort-img"><img src="${esc(reduireImage(a.image))}" alt=""></div>` : ''}
    <div class="fort-meta">
      <span class="repere">Temps fort</span>
      <span class="badge" style="background:${a.couleur}">${esc(a.source)}</span>
      ${esc(a.categorie || '')}${a.categorie ? ' · ' : ''}${jourCourt(new Date(a.date))} ${heure(new Date(a.date))}
      ${a.angles?.length ? ` · repris par ${a.angles.length} autre${a.angles.length > 1 ? 's' : ''} titre${a.angles.length > 1 ? 's' : ''}` : ''}
    </div>
    <h3 class="fort-titre"><a href="${esc(a.lien)}">${a.titreHtml}</a></h3>
    ${a.resumeHtml ? `<p class="fort-resume">${a.resumeHtml}</p>` : ''}
    ${a.chiffres && a.chiffres.length ? `<div class="puces">${puces(a)}</div>` : ''}
    ${blocDeveloppement(a)}
    ${blocAngles(a)}
  </article>`;

// « L'essentiel » est présenté en texte seul. Une photo n'était disponible que
// pour une partie des articles, et cette irrégularité cassait l'unité de la
// section tout en la faisant ressembler aux cartes par journal, qui ont elles
// une vignette. Trois formes distinctes valent mieux qu'un continuum flou :
// grande image pour les temps forts, texte seul ici, vignette par journal.
const carteEssentiel = (a) => `
  <article class="carte carte--essentiel carte--texte">
    <div class="carte-txt">
      <div class="carte-meta">
        <span class="repere">L’essentiel</span>
        <span class="badge" style="background:${a.couleur}">${esc(a.source)}</span>
        ${esc(a.categorie || '')}${a.categorie ? ' · ' : ''}${jourCourt(new Date(a.date))} ${heure(new Date(a.date))}
      </div>
      <h3 class="carte-titre"><a href="${esc(a.lien)}">${a.titreHtml}</a></h3>
      ${a.resumeHtml ? `<p class="carte-resume">${a.resumeHtml}</p>` : ''}
      ${a.chiffres && a.chiffres.length ? `<div class="puces">${puces(a)}</div>` : ''}
      ${blocDeveloppement(a)}
    </div>
  </article>`;

const carteUne = (a) => `
  <article class="carte">
    ${a.image ? `<div class="carte-img"><img src="${esc(reduireImage(a.image))}" alt=""></div>` : ''}
    <div class="carte-txt">
      <div class="carte-meta">${[esc(a.categorie || a.fluxLibelle || ''), `${jourCourt(new Date(a.date))} ${heure(new Date(a.date))}`].filter(Boolean).join(' · ')}</div>
      <h3 class="carte-titre"><a href="${esc(a.lien)}">${a.titreHtml}</a></h3>
      ${a.resumeHtml ? `<p class="carte-resume">${a.resumeHtml}</p>` : ''}
      ${a.chiffres && a.chiffres.length ? `<div class="puces">${puces(a)}</div>` : ''}
      ${blocDeveloppement(a)}
    </div>
  </article>`;

const ligneBreve = (a) => `
  <li class="breve">
    <span class="breve-date">${jourCourt(new Date(a.date))}</span>
    <span class="breve-corps">
      <a class="breve-titre" href="${esc(a.lien)}">${a.titreHtml}</a>
      ${a.resumeHtml ? `<span class="breve-resume">${a.resumeHtml}</span>` : ''}
    </span>
  </li>`;

const html = `<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Revue de presse</title><style>
*{box-sizing:border-box}
html{-webkit-print-color-adjust:exact;print-color-adjust:exact}
