  json: {
    nomFichier: `revue-de-presse-${stamp}.pdf`,
    nomArchive: `revue-de-presse-${horodatage}.pdf`,
    sujet: `Revue de presse — les actualités ${periode}`,
    destinataire: cfg.destinataire,
    expediteur: cfg.expediteur,
    periode,
    nbArticles: articles.length,
    nbSujetsCommuns: sujets.length,
    // Sentinelle de non-régression : une photo qui disparaît ne fait pas échouer
    // le rapport, elle le rend seulement plus pauvre. Ce compteur, relayé dans
    // l'état, est le seul endroit où la perte se voit.
    cartesAvecImage: journaux.reduce((n, j) => n + j.une.filter((a) => a.image).length, 0),
    cartesTotal: journaux.reduce((n, j) => n + j.une.length, 0),
    maxPdfMo: cfg.maxPdfMo,
    repartition: journaux.map((j) => ({ source: j.source, total: j.total, une: j.une.length })),
    chiffresCles: chiffresCles.map((c) => ({ texte: c.texte, type: c.type, source: c.article.source })),
  },
  binary: {
    'index.html': await enBinaire(html, 'index.html', 'text/html'),
    'footer.html': await enBinaire(pied, 'footer.html', 'text/html'),
    'index-leger.html': await enBinaire(htmlLeger, 'index.html', 'text/html'),
  },
}];

// ─── Contrôle du poids du PDF ──────────────────────────────────────────────
// Gmail refuse au-delà de 25 Mo. Si le rapport dépasse le seuil même compressé,
// on bascule sur la version sans images produite par le nœud de composition.
//
// Deux pièges du bac à sable n8n, tous deux rencontrés :
//   · l'opérateur « in » ne fonctionne pas sur les objets exposés (proxies) —
//     il faut tester la valeur, pas la clé ;
//   · en mode de stockage « filesystem », la chaîne « data » est une simple
//     référence de 13 caractères : sa longueur ne dit rien du poids réel.
// On s'appuie donc sur fileSize, que n8n renseigne dans les deux modes.

const rapport = $('Composer le rapport HTML').first();
const item = $input.first();
const limite = (rapport.json.maxPdfMo || 20) * 1024 * 1024;

let binaire = item.binary?.data ? item.binary : null;
let origine = 'compressé';
if (!binaire) {
  let brut = null;
  for (const nom of ['Convertir en PDF (Gotenberg)', 'Convertir en PDF (PDFShift — secours)']) {
    try { const r = $(nom).first(); if (r?.binary?.data) { brut = r; break; } } catch (e) { /* moteur inactif */ }
  }
  if (!brut?.binary?.data) throw new Error('PDF absent : vérifier Gotenberg et le compresseur.');
  binaire = brut.binary;
  origine = 'non compressé (compresseur injoignable)';
}

const enOctets = (libelle) => {
  const m = String(libelle || '').match(/([\d.,]+)\s*([kMG]?B)/i);
  if (!m) return 0;
  const unites = { B: 1, KB: 1000, MB: 1000000, GB: 1000000000 };
  return Math.round(parseFloat(m[1].replace(',', '.')) * (unites[m[2].toUpperCase()] || 1));
};

let octets = enOctets(binaire.data.fileSize);
if (!octets) {
  // Repli : contenu en base64 (mode mémoire) puis lecture du buffer.
  const brut = binaire.data.data;
  if (typeof brut === 'string' && brut.length > 64) octets = Math.floor(brut.length * 0.75);
  else {
    try {
      const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
      octets = buf?.length || 0;
    } catch (e) { /* helper indisponible dans ce contexte */ }
  }
}

const tropLourd = octets > limite;

return [{
  json: {
    ...rapport.json,
    origine,
    tailleOctets: octets,
    tailleMo: Math.round((octets / 1048576) * 100) / 100,
    limiteMo: limite / 1048576,
    tropLourd,
    versionAllegee: tropLourd,
  },
  binary: binaire,
}];

// ─── Bascule vers la version sans images ───────────────────────────────────
// N'est atteint que si le PDF illustré dépasse le seuil. On repasse à Gotenberg
// le HTML allégé déjà préparé par le nœud de composition.

const rapport = $('Composer le rapport HTML').first();
const info = $input.first().json;

return [{
  json: info,
  binary: {
    'index.html': rapport.binary['index-leger.html'],
    'footer.html': rapport.binary['footer.html'],
  },
}];

// ─── Nommage du PDF et corps de l'e-mail ───────────────────────────────────

const rapport = $('Composer le rapport HTML').first().json;
const item = $input.first();

// Le PDF renvoyé par Gotenberg s'appelle « index.pdf » : on le renomme.
const bin = item.binary?.data;
if (!bin) throw new Error('PDF absent : vérifier le nœud de conversion (Gotenberg joignable ?).');
bin.fileName = rapport.nomFichier;
bin.fileExtension = 'pdf';
bin.mimeType = 'application/pdf';

const puce = (c) => {
  const teintes = {
    pourcentage: 'background:#fef1c7;color:#8a4b06;border:1px solid #e5a72a',
    montant: 'background:#d9f7e3;color:#10633a;border:1px solid #2f9c62',
    volume: 'background:#dbe8ff;color:#17408f;border:1px solid #4272d6',
  };
  return `<span style="display:inline-block;${teintes[c.type] || teintes.volume};border-radius:20px;
    padding:3px 10px;font-size:12px;font-weight:700;margin:0 5px 6px 0;">${c.texte}</span>`;
};

const corpsHtml = `
<div style="font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;max-width:620px;margin:0 auto;color:#16181d">
  <div style="background:#16181d;color:#fff;padding:26px 28px;border-radius:6px 6px 0 0">
    <div style="font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:#a7adba;margin-bottom:10px">
      Veille presse · 5 titres nationaux</div>
    <div style="font-size:26px;font-weight:600">Revue de presse</div>
    <div style="font-size:15px;color:#e7e9ee;margin-top:6px">${rapport.periode}</div>
  </div>
  <div style="border:1px solid #e2e5ea;border-top:0;border-radius:0 0 6px 6px;padding:24px 28px">
    <p style="margin:0 0 8px;font-size:16px;line-height:1.55">
      Bonjour,
    </p>
    <p style="margin:0 0 16px;font-size:15px;line-height:1.6">
      Voici les actualités ${rapport.periode}, réunies depuis <strong>Le Monde</strong>,
      <strong>Le Figaro</strong>, <strong>Le Parisien</strong>, <strong>Libération</strong>
      et <strong>La Croix</strong>.
    </p>
    <p style="margin:0 0 16px;font-size:15px;line-height:1.6">
      Le rapport complet est en pièce jointe : <strong>${rapport.nbArticles} articles</strong>,
      les unes comme les sujets plus courts. Les données chiffrées y sont surlignées,
      et les principaux sujets sont développés en quelques paragraphes.
    </p>
    <table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:20px">
      ${rapport.repartition.map((r) => `
      <tr>
        <td style="padding:7px 0;border-bottom:1px solid #eef0f4">${r.source}</td>
        <td style="padding:7px 0;border-bottom:1px solid #eef0f4;text-align:right;color:#5c6270">
          ${r.total} article${r.total > 1 ? 's' : ''} · ${r.une} à la une</td>
      </tr>`).join('')}
    </table>
    ${rapport.chiffresCles.length ? `
      <div style="font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:#5c6270;margin-bottom:10px">
        Chiffres qui ressortent</div>
      <div>${rapport.chiffresCles.slice(0, 8).map(puce).join('')}</div>` : ''}
    ${rapport.nbSujetsCommuns ? `
      <p style="margin:18px 0 0;font-size:13px;color:#5c6270">
        ${rapport.nbSujetsCommuns} sujet${rapport.nbSujetsCommuns > 1 ? 's' : ''} traité${rapport.nbSujetsCommuns > 1 ? 's' : ''}
        par plusieurs journaux — détaillé${rapport.nbSujetsCommuns > 1 ? 's' : ''} en page de garde.</p>` : ''}
    <p style="margin:22px 0 0;font-size:14px;line-height:1.6">Bonne lecture.</p>
    <p style="margin:18px 0 0;font-size:12px;color:#989eae;border-top:1px solid #eef0f4;padding-top:14px">
      Sources : flux RSS officiels des cinq quotidiens ; développements tirés de France Info,
      France 24, RFI et Euronews, avec mention de leur origine.
      Rapport généré automatiquement tous les 3 jours à 8 h.
    </p>
  </div>
</div>`;

return [{ json: { ...rapport, corpsHtml }, binary: item.binary }];

// ─── Mémoire d'un rapport à l'autre ────────────────────────────────────────
// Conserve la date de l'envoi et les liens déjà expédiés, pour que le rapport
// suivant reparte exactement d'où celui-ci s'arrête : ni trou après une
// exécution retardée, ni doublon après un lancement manuel.

const articles = $('Extraire et surligner les chiffres').all().map((i) => i.json);
const info = $input.first();

const liensActuels = articles.map((a) => a.lien.split('?')[0].replace(/\/$/, ''));
const anciens = $('Configuration').first().json.dejaEnvoyes || [];

// On garde de quoi couvrir deux rapports : au-delà, la fenêtre de dates suffit.
const liens = [...new Set([...liensActuels, ...anciens])].slice(0, 900);

// Trace de la décision sur le poids du PDF : le journal d'exécution de n8n est
// tronqué, ce fichier ne l'est pas.
let diagnostic = null;
try {
  const v = $('Vérifier la taille du PDF').first();
  diagnostic = {
    origine: v.json.origine,
    cartes: { avecImage: v.json.cartesAvecImage, total: v.json.cartesTotal },
    images: (() => { try { const a = $('Intégrer les images').first().json;
      return { integrees: a.imagesIntegrees, retirees: a.imagesRetirees }; } catch (e) { return null; } })(),
    qualite: (() => { try { return $('Appliquer le contrôle qualité').first().json.controleQualite; } catch (e) { return null; } })(),
    tailleMo: v.json.tailleMo,
    tropLourd: v.json.tropLourd,
    binairesRecus: Object.fromEntries(Object.entries(v.binary || {}).map(([k, b]) => [k, b.fileSize])),
    binaireEnvoye: Object.fromEntries(Object.entries(info.binary || {}).map(([k, b]) => [k, b.fileSize])),
  };
} catch (e) { diagnostic = { erreur: String(e).slice(0, 200) }; }

const etat = {
  dernierRun: new Date().toISOString(),
  diagnostic,
  dernierFichier: info.json.nomArchive || info.json.nomFichier,
  nbArticles: articles.length,
  liens,
};

const contenu = JSON.stringify(etat, null, 2);
let bin;
try {
  bin = await this.helpers.prepareBinaryData(Buffer.from(contenu, 'utf8'), '.etat.json', 'application/json');
} catch (e) {
  bin = { data: Buffer.from(contenu, 'utf8').toString('base64'), mimeType: 'application/json', fileName: '.etat.json', fileExtension: 'json' };
}

// Le PDF doit rester attaché pour le nœud d'envoi qui suit.
return [{ json: info.json, binary: { ...info.binary, etat: bin } }];
